;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_iftrue
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue:
			beq kw_git_go
			addq.l #4, sp
			rts
kw_git_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_ifzero
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero:
			movea.l (sp)+, a0
			tst.w (a0)
			beq kw_giz_go
			addq.l #4, sp
			rts
kw_giz_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d1
			cmp.w (a0), d1
			blt ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_next1v ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			addq.w #1, (a0)
			bvs ntc_for_skip
			move.w (a1), d1
			cmp.w (a0), d1
			bge ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_nextdnl ntc_for_jump
;kw_nextdnl, <var>, <literal step>, <literal limit>, <toplabel>
;  NEXT for a negative STEP: add, back to the top while var >= limit
kw_nextdnl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			move.l (sp)+, d1
			add.w d0, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			ble ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			seq d0
			ext.w d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

; ============================================================
; Arithmetic (16 bit, wrapping)
; ============================================================

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			add.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			add.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_subvv
;kw_subvv, <var1>, <var2>, <destvar>  - var1 - var2
kw_subvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvv
;kw_mulvv, <var1>, <var2>, <destvar>  - low 16 bits
kw_mulvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			muls.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_div
; d0.w / d1.w signed, truncating: d0.w = quotient, d1.w = remainder (the
; dividend's sign). Divide by zero: quotient 0, remainder = dividend.
; -32768 / -1: quotient -32768, remainder 0 (as the Z80 library). jmp (a6)
ntc_div:
			tst.w d1
			beq ntc_div_z
			ext.l d0
			move.l d0, d2
			divs.w d1, d0
			bvs ntc_div_ov
			move.l d0, d1
			swap d1
			jmp (a6)
ntc_div_z:
			move.w d0, d1
			moveq #0, d0
			jmp (a6)
ntc_div_ov:
			move.w #$8000, d0
			moveq #0, d1
			jmp (a6)

			even
;## kw_divvv ntc_div
;kw_divvv, <var1>, <var2>, <destvar>  - var1 \ var2
kw_divvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_div_q, a6
			bra ntc_div
kw_div_q:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_modvv ntc_div
;kw_modvv, <var1>, <var2>, <destvar>  - var1 MOD var2
kw_modvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_mod_r, a6
			bra ntc_div
kw_mod_r:
			movea.l (sp)+, a0
			move.w d1, (a0)
			rts

			even
;## kw_negv
kw_negv:
			movea.l (sp)+, a0
			move.w (a0), d0
			neg.w d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_andvv
kw_andvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			and.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_andvl
kw_andvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			and.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scpltvl ntc_cmp
kw_scpltvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_slt

			even
;## kw_scplevl ntc_cmp
kw_scplevl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sle

			even
;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sgt

			even
;## kw_scpgevl ntc_cmp
kw_scpgevl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sge

			even
;## kw_cpeqvv
kw_cpeqvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			cmp.w (a1), d0
			rts

			even
;## kw_cpeqvl
kw_cpeqvl:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			cmp.w (a0), d1
			rts

			even
;## kw_lptrtov8
;kw_lptrtov8, <literaladdr>, <destvar>  - PEEK(literal)
kw_lptrtov8:
			move.l (sp)+, d0
			movea.w d0, a0
			moveq #0, d0
			move.b (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vptrtov8
;kw_vptrtov8, <addrvar>, <destvar>  - PEEK(var)
kw_vptrtov8:
			movea.l (sp)+, a0
			movea.w (a0), a0
			moveq #0, d0
			move.b (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vptrtov
;kw_vptrtov, <addrvar>, <destvar>  - DEEK(var)
kw_vptrtov:
			movea.l (sp)+, a0
			movea.w (a0), a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ltovptr8
;kw_ltovptr8, <literal>, <addrvar>  - POKE var, literal
kw_ltovptr8:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			movea.w (a0), a0
			move.b d0, (a0)
			rts

			even
;## kw_ltolptr8
;kw_ltolptr8, <literal>, <literaladdr>  - POKE literal, literal
kw_ltolptr8:
			move.l (sp)+, d0
			move.l (sp)+, d1
			movea.w d1, a0
			move.b d0, (a0)
			rts

			even
;## kw_ltovptr
;kw_ltovptr, <literal>, <addrvar>  - DOKE var, literal
kw_ltovptr:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			movea.w (a0), a0
			move.w d0, (a0)
			rts

			even
;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w 0(a0, d0.l), (a1)
			rts

			even
;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## kw_erase
;kw_erase, <base>, <bytes>  - Erase of a fixed size array: zero it
kw_erase:
			movea.l (sp)+, a0
			move.l (sp)+, d0
ntc_zerofill:					; a0 = start, d0.w = bytes (unsigned)
			andi.l #$FFFF, d0
			beq ntc_zf_end
			subq.l #1, d0
ntc_zf_lp:
			clr.b (a0)+
			dbra d0, ntc_zf_lp
ntc_zf_end:
			rts

			even
;## kw_redim kw_erase
;kw_redim, <descriptor>, <base>, <lower>, <size>, <count>, <clear>  - ReDim: fill the
;  descriptor (1 dimension); clear <> 0: zero the elements. Descriptor (12 bytes):
;  base (16 bits: RAM), lower 1, lower 2, count 1, count 2, element size
kw_redim:
			movea.l (sp)+, a1
			move.l (sp)+, d3			; base
			move.l (sp)+, d4			; lower
			move.l (sp)+, d5			; size
			move.l (sp)+, d6			; count
			move.l (sp)+, d7			; clear
			move.w d3, (a1)
			move.w d4, 2(a1)
			clr.w 4(a1)
			move.w d6, 6(a1)
			move.w #1, 8(a1)
			move.w d5, 10(a1)
			tst.w d7
			beq kw_rd_end
			movea.l d3, a0
			mulu.w d5, d6
			move.l d6, d0
kw_rd_lp:
			clr.b (a0)+
			subq.l #1, d0
			bhi kw_rd_lp
kw_rd_end:
			rts

; ============================================================
; Random (16 bit xorshift 7,9,8 - the Z80 library's sequence)
; ============================================================

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcpyn kw_strcpy
;kw_strcpyn, <destaddr>, <srcaddr>, <capacity>  - into an array element (no capacity byte)
kw_strcpyn:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (sp)+, d1
			andi.w #$FF, d1
			bra ntc_strcpy_lp

			even
;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
kw_sc_end:
			tst.b (a1)
			beq kw_sc_copy
			addq.l #1, a1
			subq.w #1, d1
			bgt kw_sc_end
			rts
kw_sc_copy:
			tst.w d1
			beq kw_sc_none
			subq.w #1, d1
kw_sc_lp:
			move.b (a0)+, (a1)+
			dbeq d1, kw_sc_lp
			beq kw_sc_none
			clr.b (a1)
kw_sc_none:
			rts

			even
;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			movea.l (sp)+, a0
			moveq #-1, d0
kw_sl_lp:
			addq.w #1, d0
			tst.b (a0)+
			bne kw_sl_lp
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printtab ntc_data ntc_plat_screen
;kw_printtab, <nvar>  - Tab(n) in Print: spaces up to column n (1 based),
;  a new line first when the cursor is already past it. n off the line: nothing
kw_printtab:
			movea.l (sp)+, a0
			move.w (a0), d2
			subq.w #1, d2
ntc_pt_go:						; d2 = the column (0 based)
			moveq #0, d0
			move.b ntc_scols, d0
			cmp.w d0, d2
			bcc ntc_pt_end			; (also below 0: unsigned)
			NTC_RS
			moveq #0, d0
			move.b ntc_curx, d0
			cmp.w d0, d2
			bcc ntc_pt_lp
			jsr ntc_plat_newline
ntc_pt_lp:
			moveq #0, d0
			move.b ntc_curx, d0
			cmp.w d0, d2
			bls ntc_pt_done
			moveq #' ', d0
			jsr ntc_plat_putc
			bra ntc_pt_lp
ntc_pt_done:
			NTC_TS
ntc_pt_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_callp
;kw_callp, <addressvar>, <arg>, ...  - CallAddr: jump to the procedure call stub whose
;  number (AddressOf on the 68000: its place in the program's ntc_aptab) is in the var
kw_callp:
			movea.l (sp)+, a0
			move.w (a0), d0
			lsl.w #2, d0
			lea ntc_aptab, a0
			movea.l 0(a0, d0.w), a0
			jmp (a0)

			even
;## ntc_atoi ntc_data
; text at a0 to a number into the var at (ntc_ivar). Spaces first, then - , then
; digits (or &H hex). Then rts (the thread).
ntc_atoi:
			moveq #0, d0				; value
			moveq #0, d2				; minus
ntc_at_sp:
			move.b (a0), d1
			cmpi.b #' ', d1
			bne ntc_at_sg
			addq.l #1, a0
			bra ntc_at_sp
ntc_at_sg:
			cmpi.b #'-', d1
			bne ntc_at_amp
			moveq #1, d2
			addq.l #1, a0
			move.b (a0), d1
ntc_at_amp:
			cmpi.b #'&', d1
			bne ntc_at_dec
			addq.l #1, a0
			move.b (a0)+, d1
			ori.b #$20, d1
			cmpi.b #'h', d1
			bne ntc_at_done
ntc_at_hex:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcs ntc_at_hd
			ori.b #$20, d1
			subi.b #'a'-'0', d1
			bcs ntc_at_done
			cmpi.b #6, d1
			bcc ntc_at_done
			addi.b #10, d1
ntc_at_hd:
			lsl.w #4, d0
			or.w d1, d0
			bra ntc_at_hex
ntc_at_dec:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcc ntc_at_done
			mulu.w #10, d0
			add.w d1, d0
			bra ntc_at_dec
ntc_at_done:
			tst.w d2
			beq ntc_at_st
			neg.w d0
ntc_at_st:
			movea.l ntc_ivar, a0
			move.w d0, (a0)
			rts

			even
;## kw_cls ntc_data ntc_plat_screen
kw_cls:
			NTC_RS
			jsr ntc_plat_cls
			NTC_TS
			rts

			even
;## kw_locatell ntc_data ntc_plat_screen
;kw_locatell, <x>, <y>  - 1 based
kw_locatell:
			move.l (sp)+, d0
			move.l (sp)+, d1
			NTC_RS
			jsr ntc_plat_locate
			NTC_TS
			rts

			even
;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame (vertical blank)
kw_frame:
			NTC_RS
			jsr ntc_plat_frame
			NTC_TS
			rts

			even
;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - the tick count (frames, 60 or 50 a second)
kw_ticks:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_ticks
			NTC_TS
			move.w d0, (a2)
			rts

; ============================================================
; String functions. Numbers are passed as the address of a word.
; Results go to a string buffer. Dest may be the same as the source.
; ============================================================

			even
;## ntc_getn
; a0 = address of a word: d0.w = its value limited to 0..255. jmp (a6). Keeps others.
ntc_getn:
			move.w (a0), d0
			bmi ntc_gn_zero
			cmpi.w #255, d0
			bls ntc_gn_ok
			move.w #255, d0
ntc_gn_ok:
			jmp (a6)
ntc_gn_zero:
			moveq #0, d0
			jmp (a6)

			even
;## kw_strleft ntc_getn
;kw_strleft, <dest>, <src>, <nvar>  - Left$(src, n)
kw_strleft:
			movea.l (sp)+, a1
			movea.l (sp)+, a2
			movea.l (sp)+, a0
			lea kw_sl_n, a6
			bra ntc_getn
kw_sl_n:
			movea.l a2, a0
; copy up to d0.w chars from a0 to a1, then the 0. rts (the thread)
ntc_strncpy:
			subq.w #1, d0
			bmi ntc_sn_end
ntc_sn_lp:
			move.b (a0)+, (a1)+
			dbeq d0, ntc_sn_lp
			beq ntc_sn_z
ntc_sn_end:
			clr.b (a1)
ntc_sn_z:
			rts

			even
;## kw_strright ntc_getn kw_strleft
;kw_strright, <dest>, <src>, <nvar>  - Right$(src, n)
kw_strright:
			movea.l (sp)+, a1
			movea.l (sp)+, a2
			movea.l (sp)+, a0
			lea kw_sr_n, a6
			bra ntc_getn
kw_sr_n:
			movea.l a2, a0
			moveq #-1, d1
kw_sr_len:
			addq.w #1, d1
			tst.b (a0)+
			bne kw_sr_len
			sub.w d0, d1				; len - n
			bpl kw_sr_skip
			moveq #0, d1
kw_sr_skip:
			lea 0(a2, d1.w), a0
			move.w #255, d0
			bra ntc_strncpy

			even
;## kw_strrev
;kw_strrev, <dest>, <src>  - StrReverse
kw_strrev:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			cmpa.l a0, a1
			beq kw_rv_go
			movea.l a1, a2
kw_rv_cl:
			move.b (a0)+, (a2)+
			bne kw_rv_cl
kw_rv_go:
			movea.l a1, a0
kw_rv_end:
			tst.b (a0)+
			bne kw_rv_end
			subq.l #2, a0
kw_rv_sw:
			cmpa.l a0, a1
			bcc kw_rv_done
			move.b (a1), d0
			move.b (a0), (a1)+
			move.b d0, (a0)
			subq.l #1, a0
			bra kw_rv_sw
kw_rv_done:
			rts

			even
;## kw_strinstrrev
;kw_strinstrrev, <text>, <find>, <startvar>, <destvar>  - InStrRev (start -1 = from the end)
kw_strinstrrev:
			movea.l (sp)+, a2			; text
			movea.l (sp)+, a3			; find
			movea.l (sp)+, a0
			move.w (a0), d4				; start
			movea.l a2, a0
			moveq #-1, d1
kw_ir_l1:
			addq.w #1, d1
			tst.b (a0)+
			bne kw_ir_l1				; d1 = len(text)
			movea.l a3, a0
			moveq #-1, d2
kw_ir_l2:
			addq.w #1, d2
			tst.b (a0)+
			bne kw_ir_l2				; d2 = len(find)
			move.w d1, d0
			sub.w d2, d0
			addq.w #1, d0				; last place it can start (1 based)
			tst.w d4
			ble kw_ir_lp
			cmp.w d0, d4
			bcc kw_ir_lp
			move.w d4, d0
kw_ir_lp:
			tst.w d0
			ble kw_ir_none
			lea -1(a2, d0.w), a0
			movea.l a3, a1
kw_ir_cmp:
			move.b (a1)+, d3
			beq kw_ir_found
			cmp.b (a0)+, d3
			beq kw_ir_cmp
			subq.w #1, d0
			bra kw_ir_lp
kw_ir_none:
			moveq #0, d0
kw_ir_found:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strreplace
;kw_strreplace, <dest>, <text>, <find>, <with>  - Replace (NTC_STRMAX characters at most)
kw_strreplace:
			movea.l (sp)+, a4			; dest
			movea.l (sp)+, a2			; text
			movea.l (sp)+, a3			; find
			movea.l (sp)+, a5			; with
			lea ntc_rpbuf, a1
			move.w #NTC_STRMAX, d4		; room
			tst.b (a3)
			beq kw_rp_rest
kw_rp_lp:
			tst.b (a2)
			beq kw_rp_done
			movea.l a2, a0
			movea.l a3, a6
kw_rp_m:
			move.b (a6)+, d0
			beq kw_rp_hit
			cmp.b (a0)+, d0
			beq kw_rp_m
			; miss: one char across
			tst.w d4
			beq kw_rp_done
			move.b (a2)+, (a1)+
			subq.w #1, d4
			bra kw_rp_lp
kw_rp_hit:
			movea.l a0, a2
			movea.l a5, a0
kw_rp_w:
			move.b (a0)+, d0
			beq kw_rp_lp
			tst.w d4
			beq kw_rp_done
			move.b d0, (a1)+
			subq.w #1, d4
			bra kw_rp_w
kw_rp_rest:
			move.b (a2)+, d0
			beq kw_rp_done
			tst.w d4
			beq kw_rp_done
			move.b d0, (a1)+
			subq.w #1, d4
			bra kw_rp_rest
kw_rp_done:
			clr.b (a1)
			lea ntc_rpbuf, a0
kw_rp_out:
			move.b (a0)+, (a4)+
			bne kw_rp_out
			rts

			even
;## kw_strlike
;kw_strlike, <text>, <pattern>  - Z if text Like pattern: * any run, ? one char,
;  # one digit, [abc] / [a-z] one of, [!abc] none of. Case matters
kw_strlike:
			movea.l (sp)+, a1			; text
			movea.l (sp)+, a0			; pattern
			suba.l a2, a2				; the last * (pattern after it), 0 none
			suba.l a3, a3				; where the text was then
kw_lk_lp:
			tst.b (a1)
			beq kw_lk_end
			move.b (a0), d0
			cmpi.b #'*', d0
			bne kw_lk_one
			addq.l #1, a0
			movea.l a0, a2
			movea.l a1, a3
			bra kw_lk_lp
kw_lk_one:
			move.b (a1), d1				; the text char
			tst.b d0
			beq kw_lk_back
			cmpi.b #'?', d0
			beq kw_lk_ok1
			cmpi.b #'#', d0
			bne kw_lk_br
			cmpi.b #'0', d1
			bcs kw_lk_back
			cmpi.b #'9'+1, d1
			bcc kw_lk_back
kw_lk_ok1:
			addq.l #1, a0
			addq.l #1, a1
			bra kw_lk_lp
kw_lk_br:
			cmpi.b #'[', d0
			bne kw_lk_lit
			addq.l #1, a0
			moveq #0, d4				; ! = 1
			cmpi.b #'!', (a0)
			bne kw_lk_c0
			moveq #1, d4
			addq.l #1, a0
kw_lk_c0:
			moveq #0, d5				; hit
kw_lk_cl:
			move.b (a0), d2
			beq kw_lk_back
			cmpi.b #']', d2
			beq kw_lk_clend
			move.b d2, d3				; lo, hi
			addq.l #1, a0
			cmpi.b #'-', (a0)
			bne kw_lk_cmp
			addq.l #1, a0
			move.b (a0), d6
			cmpi.b #']', d6
			beq kw_lk_dash
			tst.b d6
			beq kw_lk_back
			move.b d6, d3
			addq.l #1, a0
			bra kw_lk_cmp
kw_lk_dash:
			subq.l #1, a0
kw_lk_cmp:
			cmp.b d2, d1
			bcs kw_lk_cl
			cmp.b d3, d1
			bhi kw_lk_cl
			moveq #1, d5
			bra kw_lk_cl
kw_lk_clend:
			addq.l #1, a0
			cmp.b d4, d5
			beq kw_lk_back
			addq.l #1, a1
			bra kw_lk_lp
kw_lk_lit:
			cmp.b d0, d1
			bne kw_lk_back
			addq.l #1, a0
			addq.l #1, a1
			bra kw_lk_lp
kw_lk_back:
			cmpa.w #0, a2
			beq kw_lk_no
			addq.l #1, a3
			movea.l a3, a1
			movea.l a2, a0
			bra kw_lk_lp
kw_lk_end:
			move.b (a0), d0
			cmpi.b #'*', d0
			bne kw_lk_e2
			addq.l #1, a0
			bra kw_lk_end
kw_lk_e2:
			tst.b d0
			rts
kw_lk_no:
			moveq #1, d0
			rts

			even
;## kw_strlset
;kw_strlset, <dest>, <src>  - LSet dest = src: src left in dest's length, spaces after
kw_strlset:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			movea.l a1, a2
			moveq #0, d1
kw_ls_len:
			tst.b (a2)+
			beq kw_ls_go
			addq.w #1, d1
			bra kw_ls_len
kw_ls_go:
			tst.w d1
			beq kw_ls_e
			subq.w #1, d1
kw_ls_cp:
			move.b (a0), d0
			beq kw_ls_pad
			addq.l #1, a0
			move.b d0, (a1)+
			dbra d1, kw_ls_cp
kw_ls_e:
			rts
kw_ls_pad:
			move.b #' ', (a1)+
			dbra d1, kw_ls_pad
			rts

			even
;## kw_strrset
;kw_strrset, <dest>, <src>  - RSet dest = src: src right in dest's length, spaces before
kw_strrset:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			movea.l a1, a2
			moveq #0, d1
kw_rs_len:
			tst.b (a2)+
			beq kw_rs_l2
			addq.w #1, d1
			bra kw_rs_len
kw_rs_l2:
			movea.l a0, a2
			moveq #0, d2
kw_rs_len2:
			tst.b (a2)+
			beq kw_rs_go
			addq.w #1, d2
			bra kw_rs_len2
kw_rs_go:
			tst.w d1
			beq kw_rs_e
			cmp.w d1, d2
			bcs kw_rs_pad
			subq.w #1, d1
kw_rs_cp:
			move.b (a0)+, (a1)+
			dbra d1, kw_rs_cp
kw_rs_e:
			rts
kw_rs_pad:
			move.w d1, d3
			sub.w d2, d3
			subq.w #1, d3
kw_rs_p:
			move.b #' ', (a1)+
			dbra d3, kw_rs_p
			tst.w d2
			beq kw_rs_e
			move.w d2, d1
			subq.w #1, d1
			bra kw_rs_cp

			even
;## kw_strfix
;kw_strfix, <var>, <n>  - String * n after a change: pad with spaces / cut to n
kw_strfix:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			andi.w #$FF, d1
			beq kw_sf_end
			subq.w #1, d1
kw_sf_len:
			tst.b (a0)
			beq kw_sf_pad
			addq.l #1, a0
			dbra d1, kw_sf_len
			clr.b (a0)
			rts
kw_sf_pad:
			move.b #' ', (a0)+
			dbra d1, kw_sf_pad
kw_sf_end:
			clr.b (a0)
			rts

			even
;## kw_strjoin
;kw_strjoin, <dest>, <descriptor>, <sep>  - Join(stringarray, sep), NTC_STRMAX characters at most
kw_strjoin:
			movea.l (sp)+, a4			; dest
			movea.l (sp)+, a0			; descriptor
			movea.w (a0), a2			; base (RAM)
			move.w 6(a0), d3			; count
			move.w 10(a0), d5			; element size
			movea.l (sp)+, a3			; sep
			lea ntc_jnbuf, a1
			move.w #NTC_STRMAX, d4
			tst.w d3
			beq kw_jn_done
kw_jn_el:
			movea.l a2, a0
kw_jn_c1:
			move.b (a0)+, d0
			beq kw_jn_eend
			tst.w d4
			beq kw_jn_done
			move.b d0, (a1)+
			subq.w #1, d4
			bra kw_jn_c1
kw_jn_eend:
			adda.w d5, a2
			subq.w #1, d3
			beq kw_jn_done
			movea.l a3, a0
kw_jn_c2:
			move.b (a0)+, d0
			beq kw_jn_el
			tst.w d4
			beq kw_jn_done
			move.b d0, (a1)+
			subq.w #1, d4
			bra kw_jn_c2
kw_jn_done:
			clr.b (a1)
			lea ntc_jnbuf, a0
kw_jn_out:
			move.b (a0)+, (a4)+
			bne kw_jn_out
			rts

			even
;## kw_strsplit
;kw_strsplit, <descriptor>, <base>, <capacity>, <text>, <sep>, <element size>  - a() = Split(text, sep)
kw_strsplit:
			movea.l (sp)+, a4			; descriptor
			move.l (sp)+, d6			; base
			move.l (sp)+, d3			; capacity (elements)
			movea.l (sp)+, a2			; text
			movea.l (sp)+, a3			; sep
			move.l (sp)+, d5			; element size
			movea.l d6, a5				; the element being filled
			moveq #0, d7				; count
			tst.b (a2)
			beq kw_sp_fin
kw_sp_elem:
			cmp.w d3, d7
			bcc kw_sp_fin
			addq.w #1, d7
			movea.l a5, a1
			move.w d5, d4
			subq.w #1, d4				; room in the element
kw_sp_ch:
			tst.b (a2)
			beq kw_sp_last
			tst.b (a3)
			beq kw_sp_nosep
			movea.l a2, a0
			movea.l a3, a6
kw_sp_m:
			move.b (a6)+, d0
			beq kw_sp_hit
			cmp.b (a0)+, d0
			beq kw_sp_m
kw_sp_nosep:
			move.b (a2)+, d0
			tst.w d4
			beq kw_sp_ch
			move.b d0, (a1)+
			subq.w #1, d4
			bra kw_sp_ch
kw_sp_hit:
			movea.l a0, a2
			clr.b (a1)
			adda.w d5, a5
			bra kw_sp_elem
kw_sp_last:
			clr.b (a1)
kw_sp_fin:
			move.w d6, (a4)
			clr.w 2(a4)
			clr.w 4(a4)
			move.w d7, 6(a4)
			move.w #1, 8(a4)
			move.w d5, 10(a4)
			rts

			even
;## kw_strmidset
;kw_strmidset, <textvar>, <startvar>, <lenvar>, <src>  - Mid$(s, start, len) = src
kw_strmidset:
			movea.l (sp)+, a1			; text
			movea.l (sp)+, a0
			move.w (a0), d0				; start
			movea.l (sp)+, a0
			move.w (a0), d1				; len
			movea.l (sp)+, a2			; src
			tst.w d0
			ble kw_ms_e
			cmpi.w #255, d0
			bhi kw_ms_e
			subq.w #1, d0
			beq kw_ms_at
kw_ms_adv:
			tst.b (a1)
			beq kw_ms_e
			addq.l #1, a1
			subq.w #1, d0
			bne kw_ms_adv
kw_ms_at:
			cmpi.w #255, d1
			bls kw_ms_len
			move.w #255, d1
kw_ms_len:
			tst.w d1
			beq kw_ms_e
			subq.w #1, d1
kw_ms_cp:
			tst.b (a1)
			beq kw_ms_e
			move.b (a2)+, d0
			beq kw_ms_e
			move.b d0, (a1)+
			dbra d1, kw_ms_cp
kw_ms_e:
			rts

			even
;## kw_strmid ntc_getn kw_strleft
;kw_strmid, <dest>, <src>, <startvar>, <lenvar>  - Mid$(src, start, len)
kw_strmid:
			movea.l (sp)+, a1
			movea.l (sp)+, a2
			movea.l (sp)+, a0
			lea kw_sm_s, a6
			bra ntc_getn
kw_sm_s:
			tst.w d0
			beq kw_sm_s1
			subq.w #1, d0
kw_sm_s1:
			tst.w d0
			beq kw_sm_len
			tst.b (a2)
			beq kw_sm_len
			addq.l #1, a2
			subq.w #1, d0
			bra kw_sm_s1
kw_sm_len:
			movea.l (sp)+, a0
			lea kw_sm_n, a6
			bra ntc_getn
kw_sm_n:
			movea.l a2, a0
			bra ntc_strncpy

			even
;## kw_strspace ntc_getn
;kw_strspace, <dest>, <nvar>  - Space$(n)
kw_strspace:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			lea kw_sps_n, a6
			bra ntc_getn
kw_sps_n:
			moveq #' ', d1
; d0.w = count (NTC_STRMAX at most), d1.b = char, a1 = dest. rts
ntc_strfill:
			cmpi.w #NTC_STRMAX, d0
			bls ntc_sf_ok
			move.w #NTC_STRMAX, d0
ntc_sf_ok:
			subq.w #1, d0
			bmi ntc_sf_end
ntc_sf_lp:
			move.b d1, (a1)+
			dbra d0, ntc_sf_lp
ntc_sf_end:
			clr.b (a1)
			rts

			even
;## kw_strstring kw_strspace
;kw_strstring, <dest>, <nvar>, <charvar>  - String$(n, char code)
kw_strstring:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			lea kw_ss_n, a6
			bra ntc_getn
kw_ss_n:
			movea.l (sp)+, a0
			move.b 1(a0), d1
			bra ntc_strfill

			even
;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_uc_lp:
			move.b (a0)+, d0
			cmpi.b #'a', d0
			bcs kw_uc_put
			cmpi.b #'z', d0
			bhi kw_uc_put
			subi.b #32, d0
kw_uc_put:
			move.b d0, (a1)+
			bne kw_uc_lp
			rts

			even
;## kw_strlcase
;kw_strlcase, <dest>, <src>  - LCase$
kw_strlcase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_lc_lp:
			move.b (a0)+, d0
			cmpi.b #'A', d0
			bcs kw_lc_put
			cmpi.b #'Z', d0
			bhi kw_lc_put
			addi.b #32, d0
kw_lc_put:
			move.b d0, (a1)+
			bne kw_lc_lp
			rts

			even
;## kw_strltrim kw_strleft
;kw_strltrim, <dest>, <src>  - LTrim$
kw_strltrim:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_lt_skip:
			cmpi.b #' ', (a0)
			bne kw_lt_copy
			addq.l #1, a0
			bra kw_lt_skip
kw_lt_copy:
			move.w #255, d0
			bra ntc_strncpy

			even
;## kw_strrtrim
;kw_strrtrim, <dest>, <src>  - RTrim$
kw_strrtrim:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
ntc_rt_go:
			movea.l a1, a2				; the start
ntc_rt_copy:
			move.b (a0)+, (a1)+
			bne ntc_rt_copy
			subq.l #1, a1				; on the 0
ntc_rt_lp:
			cmpa.l a2, a1
			beq ntc_rt_e
			cmpi.b #' ', -1(a1)
			bne ntc_rt_e
			subq.l #1, a1
			clr.b (a1)
			bra ntc_rt_lp
ntc_rt_e:
			rts

			even
;## kw_strtrim kw_strrtrim
;kw_strtrim, <dest>, <src>  - Trim$
kw_strtrim:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_tr_skip:
			cmpi.b #' ', (a0)
			bne ntc_rt_go
			addq.l #1, a0
			bra kw_tr_skip

			even
;## kw_strasc
;kw_strasc, <src>, <destvar>  - Asc(src), 0 if empty
kw_strasc:
			movea.l (sp)+, a0
			moveq #0, d0
			move.b (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strval ntc_atoi
;kw_strval, <src>, <destvar>  - Val(src): decimal or &H hex
kw_strval:
			movea.l (sp)+, a0
			move.l (sp)+, ntc_ivar
			bra ntc_atoi

			even
;## kw_strinstr ntc_getn
;kw_strinstr, <startvar>, <s1>, <s2>, <destvar>  - InStr(start, s1, s2)
kw_strinstr:
			movea.l (sp)+, a0
			lea kw_in_s, a6
			bra ntc_getn
kw_in_s:
			tst.w d0
			bne kw_in_s1
			moveq #1, d0
kw_in_s1:
			movea.l (sp)+, a2			; s1
			movea.l (sp)+, a3			; s2
			move.w d0, d1
kw_in_adv:
			subq.w #1, d1
			beq kw_in_try
			tst.b (a2)+
			bne kw_in_adv
			bra kw_in_nf
kw_in_try:
			movea.l a2, a0
			movea.l a3, a1
kw_in_cmp:
			move.b (a1)+, d2
			beq kw_in_found
			cmp.b (a0)+, d2
			beq kw_in_cmp
			tst.b (a2)+
			beq kw_in_nf
			addq.w #1, d0
			bra kw_in_try
kw_in_nf:
			moveq #0, d0
kw_in_found:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_strcmp
; a0 = a, a1 = b: compare, jmp (a6) with Z = equal, C = a < b (unsigned bytes)
ntc_strcmp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne ntc_scm_e
			tst.b d0
			bne ntc_strcmp
ntc_scm_e:
			jmp (a6)

			even
;## kw_strcmplt ntc_strcmp
;kw_strcmplt, <a>, <b>  - Z if a < b
kw_strcmplt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_sclt, a6
			bra ntc_strcmp
kw_sclt:
			scs d0
			addq.b #1, d0
			rts

			even
;## kw_strcmpgt ntc_strcmp
kw_strcmpgt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_scgt, a6
			bra ntc_strcmp
kw_scgt:
			shi d0
			addq.b #1, d0
			rts

			even
;## ntc_paddr
; a0 = descriptor, a1 = index var: a0 = element address, d1 = element size. jmp (a6)
ntc_paddr:
			move.w (a1), d0
			sub.w 2(a0), d0				; element number
ntc_pa_tail:					; d0.w = element number, a0 = descriptor
			move.w 10(a0), d1
			movea.w (a0), a0
			muls.w d1, d0
			adda.l d0, a0
			jmp (a6)

			even
;## kw_pget ntc_paddr
;kw_pget, <descriptor>, <indexvar>, <dest>  - dest = parameter array(index)
kw_pget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pg_a, a6
			bra ntc_paddr
kw_pg_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: into the Integer's low byte
			bne kw_pg_n1
			clr.b (a1)+
kw_pg_n1:
			subq.w #1, d1
kw_pg_lp:
			move.b (a0)+, (a1)+
			dbra d1, kw_pg_lp
			rts

			even
;## kw_pset ntc_paddr
;kw_pset, <descriptor>, <indexvar>, <src>  - parameter array(index) = src
kw_pset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_ps_a, a6
			bra ntc_paddr
kw_ps_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: from the Integer's low byte
			bne kw_ps_n1
			addq.l #1, a1
kw_ps_n1:
			subq.w #1, d1
kw_ps_lp:
			move.b (a1)+, (a0)+
			dbra d1, kw_ps_lp
			rts

			even
;## kw_lbound
;kw_lbound, <descriptor + 2 * (dimension - 1)>, <dest>  - LBound
kw_lbound:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

			even
;## kw_ubound
;kw_ubound, <descriptor + 2 * (dimension - 1)>, <dest>  - UBound = lower bound + count - 1
kw_ubound:
			movea.l (sp)+, a0
			move.w 2(a0), d0
			add.w 6(a0), d0
			subq.w #1, d0
			movea.l (sp)+, a1
			move.w d0, (a1)
			rts

; ============================================================
; Long (32 bit signed): a 68000 long. Every argument is an address
; (a literal is a dc.l in the ROM).
; ============================================================

			even
;## kw_l_mov
kw_l_mov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), (a1)
			rts

			even
;## kw_l_itol
;kw_l_itol, <intvar>, <dest>  - Integer to Long (sign extended)
kw_l_itol:
			movea.l (sp)+, a0
			move.w (a0), d0
			ext.l d0
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## kw_l_ltoi
;kw_l_ltoi, <long>, <intdest>  - Long to Integer (low 16 bits)
kw_l_ltoi:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

			even
;## kw_l_add
kw_l_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			add.l (a1), d0
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## kw_l_sub
kw_l_sub:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			sub.l (a1), d0
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## kw_l_neg
kw_l_neg:
			movea.l (sp)+, a0
			move.l (a0), d0
			neg.l d0
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## ntc_lcmp
; tails: d0 = a (long), d1 = b: Z if a <rel> b
ntc_lcmp_lt:
			cmp.l d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_lcmp_le:
			cmp.l d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_lcmp_gt:
			cmp.l d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_lcmp_ge:
			cmp.l d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_lcmp_ne:
			cmp.l d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_l_cplt ntc_lcmp
kw_l_cplt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_lt

			even
;## kw_l_cpgt ntc_lcmp
kw_l_cpgt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_gt

			even
;## kw_l_cpeq
kw_l_cpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			cmp.l (a1), d0
			rts

			even
;## ntc_lmul
; d0.l * d1.l -> d0.l (low 32 bits). jmp (a6). Uses d2, d3
ntc_lmul:
			move.l d0, d2
			move.l d1, d3
			swap d2
			swap d3
			mulu.w d1, d2				; a_hi * b_lo
			mulu.w d0, d3				; a_lo * b_hi
			add.w d3, d2
			swap d2
			clr.w d2
			mulu.w d1, d0				; a_lo * b_lo
			add.l d2, d0
			jmp (a6)

			even
;## ntc_ldiv
; d0.l / d1.l signed, truncating: d0 = quotient, d1 = remainder (the dividend's
; sign). Divide by 0: quotient 0, remainder = dividend. jmp (a6). Uses d2-d5
ntc_ldiv:
			tst.l d1
			bne ntc_ld_nz
			move.l d0, d1
			moveq #0, d0
			jmp (a6)
ntc_ld_nz:
			move.l d0, d4				; the dividend's sign
			move.l d0, d5
			eor.l d1, d5				; the quotient's sign
			tst.l d0
			bpl ntc_ld_ap
			neg.l d0
ntc_ld_ap:
			tst.l d1
			bpl ntc_ld_bp
			neg.l d1
ntc_ld_bp:
			moveq #0, d2				; remainder
			moveq #31, d3
ntc_ld_lp:
			add.l d0, d0
			addx.l d2, d2
			cmp.l d1, d2
			bcs ntc_ld_no
			sub.l d1, d2
			addq.l #1, d0
ntc_ld_no:
			dbra d3, ntc_ld_lp
			tst.l d5
			bpl ntc_ld_qp
			neg.l d0
ntc_ld_qp:
			move.l d2, d1
			tst.l d4
			bpl ntc_ld_rp
			neg.l d1
ntc_ld_rp:
			jmp (a6)

			even
;## kw_l_mul ntc_lmul
kw_l_mul:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			lea kw_lmu_b, a6
			bra ntc_lmul
kw_lmu_b:
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## kw_l_div ntc_ldiv kw_l_mul
kw_l_div:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			lea kw_lmu_b, a6
			bra ntc_ldiv

			even
;## kw_l_mod ntc_ldiv
kw_l_mod:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			lea kw_lmd_b, a6
			bra ntc_ldiv
kw_lmd_b:
			movea.l (sp)+, a0
			move.l d1, (a0)
			rts

			even
;## ntc_ltoa ntc_data
; the Long d0 to text at a1, a 0 at the end (a1 on it). jmp (a6). Uses d0-d3, a0
ntc_ltoa:
			tst.l d0
			bpl ntc_lta_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_lta_pos:
			lea ntc_lta_tmp+12, a0
			clr.b -(a0)
ntc_lta_lp:
			; d0 unsigned / 10: high word first
			move.l d0, d2
			clr.w d2
			swap d2
			divu.w #10, d2				; d2 = rem:quot of the high word
			move.w d2, d3				; the quotient's high word
			move.w d0, d2				; rem (high) : low word
			divu.w #10, d2
			swap d3
			move.w d2, d3				; d3 = the quotient
			swap d2
			addi.b #'0', d2
			move.b d2, -(a0)
			move.l d3, d0
			bne ntc_lta_lp
ntc_lta_cp:
			move.b (a0)+, (a1)+
			bne ntc_lta_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_l_print ntc_ltoa ntc_printbuf
kw_l_print:
			movea.l (sp)+, a0
			move.l (a0), d0
			lea ntc_numbuf, a1
			lea kw_lpr_b, a6
			bra ntc_ltoa
kw_lpr_b:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_l_str ntc_ltoa
kw_l_str:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (a0), d0
			bmi kw_lst_go
			move.b #' ', (a1)+
kw_lst_go:
			lea ntc_next, a6
			bra ntc_ltoa

			even
;## kw_l_hex
;kw_l_hex, <dest>, <long>  - Hex$(Long): upper case, no leading zeros
kw_l_hex:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (a0), d0
			moveq #7, d1
			moveq #0, d3
kw_lhx_lp:
			rol.l #4, d0
			move.w d0, d2
			andi.w #$F, d2
			bne kw_lhx_out
			tst.w d3
			bne kw_lhx_out
			tst.w d1
			bne kw_lhx_next
kw_lhx_out:
			moveq #1, d3
			addi.b #'0', d2
			cmpi.b #'9'+1, d2
			bcs kw_lhx_put
			addq.b #7, d2
kw_lhx_put:
			move.b d2, (a1)+
kw_lhx_next:
			dbra d1, kw_lhx_lp
			clr.b (a1)
			rts

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "Not enough memory for the arrays", 0
			even

			even
;## ntc_md_boot ntc_plat_data ntc_data ntc_md_vdp ntc_md_fontdata ntc_plat_screen
; ------------------------------------------------------------
; the start ($200): TMSS, the Z80 held, RAM cleared and the RAM block copied
; from the ROM, the VDP, the font, the pads, the PSG quiet; then user mode
; on the real stack and into ntc_start
; ------------------------------------------------------------
VDP_DATA	equ $C00000
VDP_CTRL	equ $C00004
PSG_PORT	equ $C00011
NTC_USTACK	equ $00FF7800			; the real stack's top
ntc_md_entry:
			move.w #$2700, sr
			move.b $A10001, d0
			andi.b #$0F, d0
			beq ntc_mb_notmss
			move.l #'SEGA', $A14000		; TMSS
ntc_mb_notmss:
			move.w #$0100, $A11100		; the Z80's bus ours
			move.w #$0000, $A11200		; and the Z80 held in reset
			lea $FF0000, a0				; RAM cleared (below the supervisor stack's last words: no)
			move.w #($8000/4)-1, d0
ntc_mb_clr:
			clr.l (a0)+
			dbra d0, ntc_mb_clr
			lea $FF8000, a0
			move.w #($8000/4)-1, d0
ntc_mb_clr2:
			clr.l (a0)+
			dbra d0, ntc_mb_clr2
			lea ntc_romend, a0			; the RAM block's first image, from the ROM
			lea ntc_ram, a1
			move.l #ntc_ramend-ntc_ram, d0
			beq ntc_mb_nodata
ntc_mb_cp:
			move.b (a0)+, (a1)+
			subq.l #1, d0
			bne ntc_mb_cp
ntc_mb_nodata:
			move.w VDP_CTRL, d0			; (the VDP's control state reset)
			lea ntc_md_vregs, a0
			moveq #ntc_md_vregs_n-1, d0
ntc_mb_reg:
			move.w (a0)+, VDP_CTRL
			dbra d0, ntc_mb_reg
			move.l #$40000000, VDP_CTRL	; VRAM 0: all clear
			move.w #$8000-1, d0
ntc_mb_vram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_vram
			move.l #$C0000000, VDP_CTRL	; CRAM
			moveq #64-1, d0
ntc_mb_cram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_cram
			move.l #$40000010, VDP_CTRL	; VSRAM
			moveq #40-1, d0
ntc_mb_vsram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_vsram
			move.l #$C0020000, VDP_CTRL	; palette 0 colour 1: the text, white
			move.w #$0EEE, VDP_DATA
			; the font: tiles 32-126 at $0400, 1 bit a pixel -> colour 1
			move.l #$44000000, VDP_CTRL
			lea ntc_md_font, a0
			move.w #95*8-1, d1
ntc_mb_font:
			move.b (a0)+, d2
			moveq #0, d3
			moveq #8-1, d4
ntc_mb_fbit:
			lsl.l #4, d3
			add.b d2, d2
			bcc ntc_mb_f0
			addq.b #1, d3
ntc_mb_f0:
			dbra d4, ntc_mb_fbit
			move.l d3, VDP_DATA
			dbra d1, ntc_mb_font
			move.w #$8174, VDP_CTRL		; the display on, the frame interrupt on
			; the pads: TH an output, high
			move.b #$40, $A10009
			move.b #$40, $A1000B
			move.b #$40, $A10003
			move.b #$40, $A10005
			; the PSG quiet
			move.b #$9F, PSG_PORT
			move.b #$BF, PSG_PORT
			move.b #$DF, PSG_PORT
			move.b #$FF, PSG_PORT
			move.b #40, ntc_scols
			move.b #28, ntc_srows
			move.l #NTC_USTACK, a0
			move.l a0, usp
			move.w #$0000, sr			; user mode, the interrupts on: A7 is now the user stack
			jmp ntc_start

ntc_md_vregs:
			dc.w $8004					; 0: no line interrupt
			dc.w $8134					; 1: display off for now, frame interrupt, DMA, 28 rows
			dc.w $8230					; 2: plane A at $C000
			dc.w $8328					; 3: the window at $A000
			dc.w $8407					; 4: plane B at $E000
			dc.w $856C					; 5: sprites at $D800
			dc.w $8600
			dc.w $8700					; 7: the backdrop: palette 0 colour 0
			dc.w $8800
			dc.w $8900
			dc.w $8AFF					; 10: line interrupt every 256 lines
			dc.w $8B00					; 11: whole screen scrolling
			dc.w $8C81					; 12: H40, no interlace
			dc.w $8D3F					; 13: horizontal scroll at $FC00
			dc.w $8E00
			dc.w $8F02					; 15: VDP address step 2
			dc.w $9001					; 16: planes 64 x 32 cells
			dc.w $9100					; 17, 18: no window
			dc.w $9200
ntc_md_vregs_n	equ (*-ntc_md_vregs)/2

; ------------------------------------------------------------
; interrupts and exceptions (supervisor mode, the supervisor stack)
; ------------------------------------------------------------
; the frame: count it, read the pads (3 or 6 button, once a frame - a 6
; button pad's counter needs the gap between reads), run the frame hook
ntc_md_vint:
			movem.l d0-d4/a0-a1, -(sp)
			addq.w #1, ntc_ticks
			addq.w #1, ntc_vbl
			lea $A10003, a0
			bsr ntc_md_pad
			move.w d0, ntc_pad1
			lea $A10005, a0
			bsr ntc_md_pad
			move.w d0, ntc_pad2
			move.l ntc_vhook, d0
			beq ntc_vi_nohook
			movea.l d0, a0
			jsr (a0)					; (keeps every register but d0-d4 / a0-a1)
ntc_vi_nohook:
			movem.l (sp)+, d0-d4/a0-a1
ntc_md_rte:
			rte
ntc_md_hint:
			rte

; a0 = the port's data register: d0 = its buttons (1 = held)
ntc_md_pad:
			move.b #$40, (a0)
			nop
			nop
			move.b (a0), d1				; ?1CBRLDU
			move.b #$00, (a0)
			nop
			nop
			move.b (a0), d2				; ?0SA00DU (TH's 2nd step)
			move.b #$40, (a0)
			nop
			nop
			move.b #$00, (a0)			; (4th: ?0SA00DU again)
			nop
			nop
			move.b #$40, (a0)
			nop
			nop
			move.b #$00, (a0)			; 6th: a 6 button pad says so here
			nop
			nop
			move.b (a0), d3				; ?0SA0000 on a 6 button pad
			move.b #$40, (a0)
			nop
			nop
			move.b (a0), d4				; ?1CBMXYZ on a 6 button pad (7th)
			move.b #$00, (a0)			; (8th: back to the start)
			nop
			nop
			move.b #$40, (a0)
			not.b d1
			not.b d2
			moveq #0, d0
			move.b d1, d0
			andi.b #$3F, d0				; Up Down Left Right B C
			lsl.b #2, d2
			andi.b #$C0, d2				; A, Start
			or.b d2, d0
			andi.b #$0F, d3
			bne ntc_mp_3b
			not.b d4
			andi.w #$0F, d4				; Z Y X Mode
			moveq #0, d1
			btst #2, d4
			beq ntc_mp_nx
			bset #8, d1					; X
ntc_mp_nx:
			btst #1, d4
			beq ntc_mp_ny
			bset #9, d1					; Y
ntc_mp_ny:
			btst #0, d4
			beq ntc_mp_nz
			bset #10, d1				; Z
ntc_mp_nz:
			btst #3, d4
			beq ntc_mp_nm
			bset #11, d1				; Mode
ntc_mp_nm:
			or.w d1, d0
ntc_mp_3b:
			rts

; an exception: its number and the PC on the console, then stop
ntc_md_ex2:	moveq #2, d7
			bra ntc_md_exg
ntc_md_ex3:	moveq #3, d7
ntc_md_exg:
			move.l 10(sp), d6			; bus / address error: the PC is further in
			bra ntc_md_exshow
ntc_md_ex4:	moveq #4, d7
			bra ntc_md_exn
ntc_md_ex5:	moveq #5, d7
			bra ntc_md_exn
ntc_md_ex6:	moveq #6, d7
			bra ntc_md_exn
ntc_md_ex7:	moveq #7, d7
			bra ntc_md_exn
ntc_md_ex8:	moveq #8, d7
			bra ntc_md_exn
ntc_md_ex9:	moveq #9, d7
			bra ntc_md_exn
ntc_md_ex10: moveq #10, d7
			bra ntc_md_exn
ntc_md_ex11: moveq #11, d7
			bra ntc_md_exn
ntc_md_exx:	moveq #0, d7
ntc_md_exn:
			move.l 2(sp), d6
ntc_md_exshow:
			move.w #$2700, sr
			move.l usp, a5				; the thread position
			jsr ntc_plat_newline
			lea ntc_md_extxt, a2
			bsr ntc_md_exstr
			move.l d7, d5
			moveq #2, d4
			bsr ntc_md_exhex
			lea ntc_md_expc, a2
			bsr ntc_md_exstr
			move.l d6, d5
			moveq #6, d4
			bsr ntc_md_exhex
			lea ntc_md_exsp, a2
			bsr ntc_md_exstr
			move.l a5, d5
			moveq #6, d4
			bsr ntc_md_exhex
ntc_md_exstop:
			bra ntc_md_exstop
ntc_md_exstr:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_md_exse
			jsr ntc_plat_putc
			bra ntc_md_exstr
ntc_md_exse:
			rts
ntc_md_exhex:					; d5 = value, d4 = digits
			move.w d4, d3
			subq.w #1, d3
			lsl.w #2, d4
			ror.l d4, d5
ntc_md_exh1:
			rol.l #4, d5
			move.w d5, d0
			andi.w #$F, d0
			addi.b #'0', d0
			cmpi.b #'9'+1, d0
			bcs ntc_md_exh2
			addq.b #7, d0
ntc_md_exh2:
			jsr ntc_plat_putc
			dbra d3, ntc_md_exh1
			rts
ntc_md_extxt:	dc.b "68000 EXCEPTION ", 0
ntc_md_expc:	dc.b " PC ", 0
ntc_md_exsp:	dc.b " SP ", 0
			even

			even
;## ntc_md_vdp
; VDP helpers on the real stack (jsr): keep d2-d7 / a2-a6
; ntc_md_vaddr: d0.w = VRAM address -> VDP_CTRL set to write there
ntc_md_vaddr:
			move.l d1, -(sp)
			moveq #0, d1
			move.w d0, d1
			andi.w #$3FFF, d1
			ori.w #$4000, d1
			swap d1
			move.w d0, d1
			rol.w #2, d1
			andi.w #3, d1
			move.l d1, VDP_CTRL
			move.l (sp)+, d1
			rts

			even
;## ntc_plat_data

			even
;## ntc_plat_screen ntc_plat_data ntc_data ntc_md_vdp ntc_md_logs
; ntc_plat_putc - d0.b = character: on plane A at the cursor, move on, a new
; line after the last column. Real stack, keeps d2-d7 / a2-a6
ntc_plat_putc:
			movem.l d0-d2/a0, -(sp)
		ifd NTC_MDLOG
			bsr ntc_md_log
		endif
			moveq #0, d1
			move.b ntc_cury, d1
			mulu.w #40, d1
			moveq #0, d2
			move.b ntc_curx, d2
			add.w d2, d1
			lea ntc_shadow, a0
			move.b d0, 0(a0, d1.w)
			bsr ntc_md_cell			; d0 = char, the cursor's cell
			addq.b #1, ntc_curx
			move.b ntc_curx, d0
			cmp.b ntc_scols, d0
			bcs ntc_pc_nowrap
			move.b #1, ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			bra ntc_nl_do
ntc_pc_nowrap:
			clr.b ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			rts

; the cell at the cursor gets character d0 (VRAM: plane A, 64 cells a row)
ntc_md_cell:
			movem.l d0-d1, -(sp)
			moveq #0, d1
			move.b ntc_cury, d1
			lsl.w #6, d1
			moveq #0, d0
			move.b ntc_curx, d0
			add.w d0, d1
			add.w d1, d1
			addi.w #$C000, d1
			move.w d1, d0
			bsr ntc_md_vaddr
			movem.l (sp)+, d0-d1
			move.l d1, -(sp)
			moveq #0, d1
			move.b ntc_tattr, d1
			lsl.w #8, d1
			move.b d0, d1
			add.w ntc_tbase, d1
			move.w d1, VDP_DATA
			move.l (sp)+, d1
			rts

; ntc_plat_newline - column 0, next row (scrolls at the bottom); nothing straight after a wrap
ntc_plat_newline:
		ifd NTC_MDLOG
			move.l d0, -(sp)
			moveq #10, d0
			bsr ntc_md_log
			move.l (sp)+, d0
		endif
			tst.b ntc_wrapped
			beq ntc_nl_do
			clr.b ntc_wrapped
			rts
ntc_nl_do:
			clr.b ntc_curx
			addq.b #1, ntc_cury
			move.b ntc_cury, d0
			cmp.b ntc_srows, d0
			bcs ntc_nl_e
			subq.b #1, ntc_cury
			bra ntc_md_scroll
ntc_nl_e:
			rts

; the text up a row: the shadow moved up, the last row cleared, plane A redrawn
ntc_md_scroll:
			movem.l d0-d3/a0-a1, -(sp)
			lea ntc_shadow, a0
			lea 40(a0), a1
			move.w #40*27-1, d0
ntc_sc_mv:
			move.b (a1)+, (a0)+
			dbra d0, ntc_sc_mv
			moveq #40-1, d0
ntc_sc_cl:
			move.b #' ', (a0)+
			dbra d0, ntc_sc_cl
			bsr ntc_md_redraw
			movem.l (sp)+, d0-d3/a0-a1
			rts

; plane A from the shadow (28 rows of 40)
ntc_md_redraw:
			movem.l d0-d3/a0, -(sp)
			lea ntc_shadow, a0
			moveq #0, d2				; row
			moveq #0, d3
			move.b ntc_tattr, d3
			lsl.w #8, d3
ntc_rd_row:
			move.w d2, d0
			lsl.w #7, d0
			addi.w #$C000, d0
			bsr ntc_md_vaddr
			moveq #40-1, d1
ntc_rd_col:
			moveq #0, d0
			move.b (a0)+, d0
			bne ntc_rd_ch
			moveq #' ', d0
ntc_rd_ch:
			or.w d3, d0
			add.w ntc_tbase, d0
			move.w d0, VDP_DATA
			dbra d1, ntc_rd_col
			addq.w #1, d2
			cmpi.w #28, d2
			bcs ntc_rd_row
			movem.l (sp)+, d0-d3/a0
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_cls - clear the console, the cursor home
ntc_plat_cls:
			movem.l d0/a0, -(sp)
			lea ntc_shadow, a0
			move.w #40*28-1, d0
ntc_cls_lp:
			move.b #' ', (a0)+
			dbra d0, ntc_cls_lp
			clr.b ntc_curx
			clr.b ntc_cury
			clr.b ntc_wrapped
			bsr ntc_md_redraw
			movem.l (sp)+, d0/a0
			rts

			even
;## ntc_plat_locate @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_locate - d0 = column, d1 = row (1 based, kept on the screen)
ntc_plat_locate:
			subq.w #1, d0
			bpl ntc_lo_x0
			moveq #0, d0
ntc_lo_x0:
			cmpi.w #39, d0
			bls ntc_lo_x1
			moveq #39, d0
ntc_lo_x1:
			subq.w #1, d1
			bpl ntc_lo_y0
			moveq #0, d1
ntc_lo_y0:
			cmpi.w #27, d1
			bls ntc_lo_y1
			moveq #27, d1
ntc_lo_y1:
			move.b d0, ntc_curx
			move.b d1, ntc_cury
			clr.b ntc_wrapped
			rts

			even
;## ntc_md_logs
		ifd NTC_MDLOG
; test builds (vasm -DNTC_MDLOG): what the console was given, at $FF0000 on (the
; harness reads it): characters, 10 for a new line. $FF6FFC: where the next goes
ntc_md_log:
			move.l a0, -(sp)
			movea.l $FF6FFC, a0
			cmpa.l #$FF0000, a0
			bcc ntc_lg_ok
			lea $FF0000, a0
ntc_lg_ok:
			cmpa.l #$FF6FF0, a0
			bcc ntc_lg_full
			move.b d0, (a0)+
			move.l a0, $FF6FFC
ntc_lg_full:
			movea.l (sp)+, a0
			rts
		endif

			even
;## ntc_plat_frame ntc_plat_data
; ntc_plat_frame - wait for the next frame interrupt (the start of the vertical blank)
ntc_plat_frame:
			move.l d0, -(sp)
			move.w ntc_vbl, d0
ntc_fr_lp:
			cmp.w ntc_vbl, d0
			beq ntc_fr_lp
			move.l (sp)+, d0
			rts

			even
;## ntc_plat_ticks ntc_plat_data
; ntc_plat_ticks - d0.w = frames since the start (60 a second, 50 on a PAL machine)
ntc_plat_ticks:
			move.w ntc_ticks, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - before the program stops: nothing to give back on a Mega Drive
ntc_plat_exit:
			rts

			even
;## ntc_md_spr ntc_md_vdp ntc_data
; ------------------------------------------------------------
; the hardware sprites: a copy of the VDP's sprite table in RAM (80 x 8 bytes:
; y + 128 (0 = hidden), size, the cell value, x + 128); ntc_md_sprupd writes it
; to the VDP ($D800) with the links 0 -> 1 -> ... -> 79. On the thread: keywords.
; ------------------------------------------------------------
; ntc_md_sprupd - the sprite table to the VDP (call it after Frame). Real stack
ntc_md_sprupd:
			movem.l d0-d2/a0, -(sp)
			move.w #$D800, d0
			bsr ntc_md_vaddr
			lea ntc_sat, a0
			moveq #1, d1				; the link
ntc_su_lp:
			move.w (a0)+, VDP_DATA		; y
			move.w (a0)+, d2			; size
			lsl.w #8, d2
			cmpi.w #80, d1
			bcc ntc_su_last
			move.b d1, d2
ntc_su_last:
			move.w d2, VDP_DATA			; size, link (the last links to 0)
			move.l (a0)+, VDP_DATA		; the cell value, x
			addq.w #1, d1
			cmpi.w #81, d1
			bcs ntc_su_lp
			movem.l (sp)+, d0-d2/a0
			rts

			even
;## ntc_md_psg ntc_data
; ------------------------------------------------------------
; the PSG's 4 channels (3 tones, the noise) as sound effects that move on a frame
; at a time (ntc_md_psgupd, from Psg.Update): a period that slides and a volume
; that fades. A channel: active, period, slide, volume, frames, left (12 bytes)
; ------------------------------------------------------------
; ntc_md_psgout - a0 = the channel's state, d3 = its number: its period and volume to the PSG
ntc_md_psgout:
			move.w 2(a0), d0			; the period
			cmpi.w #3, d3
			beq ntc_po_noise
			move.w d3, d1
			lsl.b #5, d1
			ori.b #$80, d1
			move.w d0, d2
			andi.b #$0F, d2
			or.b d2, d1
			move.b d1, PSG_PORT
			lsr.w #4, d0
			andi.b #$3F, d0
			move.b d0, PSG_PORT
			bra ntc_po_vol
ntc_po_noise:
			andi.b #7, d0
			ori.b #$E0, d0
			move.b d0, PSG_PORT
ntc_po_vol:
			; the volume now: volume * left / frames (frames 0: the volume)
			move.w 6(a0), d0
			move.w 8(a0), d1
			beq ntc_po_v
			mulu.w 10(a0), d0
			divu.w d1, d0
ntc_po_v:
			moveq #15, d1
			sub.w d0, d1				; the attenuation
			bcc ntc_po_v2
			moveq #0, d1
ntc_po_v2:
			move.w d3, d0
			lsl.b #5, d0
			ori.b #$90, d0
			andi.b #$0F, d1
			or.b d1, d0
			move.b d0, PSG_PORT
			rts

; ntc_md_psgoff - d3 = the channel: silent, not active
ntc_md_psgoff:
			move.w d3, d0
			mulu.w #12, d0
			lea ntc_psgch, a0
			clr.w 0(a0, d0.w)
			move.w d3, d0
			lsl.b #5, d0
			ori.b #$9F, d0
			move.b d0, PSG_PORT
			rts

; ntc_md_psgupd - every active channel a frame on
ntc_md_psgupd:
			movem.l d0-d3/a0, -(sp)
			moveq #0, d3
			lea ntc_psgch, a0
ntc_pu_lp:
			tst.w (a0)
			beq ntc_pu_next
			move.w 8(a0), d0			; frames: 0 = held until stopped
			beq ntc_pu_slide
			subq.w #1, 10(a0)
			bgt ntc_pu_slide
			move.l a0, -(sp)
			bsr ntc_md_psgoff
			movea.l (sp)+, a0
			bra ntc_pu_next
ntc_pu_slide:
			move.w 4(a0), d0
			add.w d0, 2(a0)
			move.w 2(a0), d0
			cmpi.w #3, d3
			beq ntc_pu_out
			cmpi.w #1, d0
			bge ntc_pu_lo
			move.w #1, 2(a0)
ntc_pu_lo:
			cmpi.w #1023, d0
			ble ntc_pu_out
			move.w #1023, 2(a0)
ntc_pu_out:
			bsr ntc_md_psgout
ntc_pu_next:
			lea 12(a0), a0
			addq.w #1, d3
			cmpi.w #4, d3
			bcs ntc_pu_lp
			movem.l (sp)+, d0-d3/a0
			rts

			even
;## ntc_md_fontdata
ntc_md_font:
			dc.b $00, $00, $00, $00, $00, $00, $00, $00		; 32
			dc.b $18, $3C, $3C, $18, $18, $00, $18, $00		; 33
			dc.b $6C, $6C, $00, $00, $00, $00, $00, $00		; 34
			dc.b $6C, $6C, $FE, $6C, $FE, $6C, $6C, $00		; 35
			dc.b $30, $7C, $C0, $78, $0C, $F8, $30, $00		; 36
			dc.b $00, $C6, $CC, $18, $30, $66, $C6, $00		; 37
			dc.b $38, $6C, $38, $76, $DC, $CC, $76, $00		; 38
			dc.b $60, $60, $C0, $00, $00, $00, $00, $00		; 39
			dc.b $18, $30, $60, $60, $60, $30, $18, $00		; 40
			dc.b $60, $30, $18, $18, $18, $30, $60, $00		; 41
			dc.b $00, $66, $3C, $FF, $3C, $66, $00, $00		; 42
			dc.b $00, $30, $30, $FC, $30, $30, $00, $00		; 43
			dc.b $00, $00, $00, $00, $00, $30, $30, $60		; 44
			dc.b $00, $00, $00, $FC, $00, $00, $00, $00		; 45
			dc.b $00, $00, $00, $00, $00, $30, $30, $00		; 46
			dc.b $06, $0C, $18, $30, $60, $C0, $80, $00		; 47
			dc.b $7C, $C6, $CE, $DE, $F6, $E6, $7C, $00		; 48
			dc.b $30, $70, $30, $30, $30, $30, $FC, $00		; 49
			dc.b $78, $CC, $0C, $38, $60, $CC, $FC, $00		; 50
			dc.b $78, $CC, $0C, $38, $0C, $CC, $78, $00		; 51
			dc.b $1C, $3C, $6C, $CC, $FE, $0C, $1E, $00		; 52
			dc.b $FC, $C0, $F8, $0C, $0C, $CC, $78, $00		; 53
			dc.b $38, $60, $C0, $F8, $CC, $CC, $78, $00		; 54
			dc.b $FC, $CC, $0C, $18, $30, $30, $30, $00		; 55
			dc.b $78, $CC, $CC, $78, $CC, $CC, $78, $00		; 56
			dc.b $78, $CC, $CC, $7C, $0C, $18, $70, $00		; 57
			dc.b $00, $30, $30, $00, $00, $30, $30, $00		; 58
			dc.b $00, $30, $30, $00, $00, $30, $30, $60		; 59
			dc.b $18, $30, $60, $C0, $60, $30, $18, $00		; 60
			dc.b $00, $00, $FC, $00, $00, $FC, $00, $00		; 61
			dc.b $60, $30, $18, $0C, $18, $30, $60, $00		; 62
			dc.b $78, $CC, $0C, $18, $30, $00, $30, $00		; 63
			dc.b $7C, $C6, $DE, $DE, $DE, $C0, $78, $00		; 64
			dc.b $30, $78, $CC, $CC, $FC, $CC, $CC, $00		; 65
			dc.b $FC, $66, $66, $7C, $66, $66, $FC, $00		; 66
			dc.b $3C, $66, $C0, $C0, $C0, $66, $3C, $00		; 67
			dc.b $F8, $6C, $66, $66, $66, $6C, $F8, $00		; 68
			dc.b $FE, $62, $68, $78, $68, $62, $FE, $00		; 69
			dc.b $FE, $62, $68, $78, $68, $60, $F0, $00		; 70
			dc.b $3C, $66, $C0, $C0, $CE, $66, $3E, $00		; 71
			dc.b $CC, $CC, $CC, $FC, $CC, $CC, $CC, $00		; 72
			dc.b $78, $30, $30, $30, $30, $30, $78, $00		; 73
			dc.b $1E, $0C, $0C, $0C, $CC, $CC, $78, $00		; 74
			dc.b $E6, $66, $6C, $78, $6C, $66, $E6, $00		; 75
			dc.b $F0, $60, $60, $60, $62, $66, $FE, $00		; 76
			dc.b $C6, $EE, $FE, $FE, $D6, $C6, $C6, $00		; 77
			dc.b $C6, $E6, $F6, $DE, $CE, $C6, $C6, $00		; 78
			dc.b $38, $6C, $C6, $C6, $C6, $6C, $38, $00		; 79
			dc.b $FC, $66, $66, $7C, $60, $60, $F0, $00		; 80
			dc.b $78, $CC, $CC, $CC, $DC, $78, $1C, $00		; 81
			dc.b $FC, $66, $66, $7C, $6C, $66, $E6, $00		; 82
			dc.b $78, $CC, $E0, $70, $1C, $CC, $78, $00		; 83
			dc.b $FC, $B4, $30, $30, $30, $30, $78, $00		; 84
			dc.b $CC, $CC, $CC, $CC, $CC, $CC, $FC, $00		; 85
			dc.b $CC, $CC, $CC, $CC, $CC, $78, $30, $00		; 86
			dc.b $C6, $C6, $C6, $D6, $FE, $EE, $C6, $00		; 87
