			dc.b $C0, $60, $30, $18, $0C, $06, $02, $00		; 92
			dc.b $78, $18, $18, $18, $18, $18, $78, $00		; 93
			dc.b $10, $38, $6C, $C6, $00, $00, $00, $00		; 94
